mapper.select:
select id,fd_filing_type_code,fd_filing_type,fd_emp_no,fd_emp_name,fd_emp_department,fd_phone, fd_auth,fd_auth_code,fd_factory_code,fd_factory,fd_filing_user_type_code,fd_filing_user_type, fd_limit,fd_limit_day,fd_long_term,fd_black,fd_approval,fd_remark, date_format(update_time,'%Y-%m-%d %H:%i:%s') update_time,update_user,fd_config_type, t1.group_code as fd_power_org_code,fd_notification from safety_enter_auth t left join (select auth_id,GROUP_CONCAT(group_code) group_code from safety_enter_link_auth_group GROUP BY auth_id) as t1 on t.id = t1.auth_id where order by t.update_time desc
limit #{offset}, #{limit}
limit #{limit}
limit 5000

select m1.emp_no as fd_emp_no,m1.emp_name as fd_emp_name,m1.phone_no as fd_phone, m1.org_code as fd_org_code, m1.org_name as fd_emp_department, m2.fd_factory_code,m2.fd_factory,m2.fd_filing_type_code,m2.fd_auth_code,m2.fd_filing_user_type_code,m2.fd_limit, m2.fd_limit_day,m2.fd_black,m2.fd_approval,m2.fd_notification from safety_employee_message m1 left join safety_enter_auth m2 on m1.emp_no = m2.fd_emp_no and m2.del = 0 where m1.status = 'NORMAL'
AND m1.emp_name = #{fdEmpName}
AND m1.emp_no = #{fdEmpNo}
AND m1.phone_no = #{fdPhone}
limit 1

select fd_filing_factory_code factoryCode,fd_filing_factory as factoryName
from safety_enter_filing
where id=#{filingId}
